INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (124, 'hotOrcBase', 'Mount do OrcamentoContent em 1 ida (CICLOS,BENEFICIOS,ENCARGOS,CARGOS,PACOTE_DRIVERS,NORMAL_DRIVERS,FORMULAS,DRE_CONFIG,CONTAS como JSON). Sem params.', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''ANO'',t.ANO,''STATUS'',t.STATUS,''CRIADO_EM'',t.CRIADO_EM,''VERSAO_ATUAL'',t.VERSAO_ATUAL,''ULTIMO_MES_REALIZADO'',t.ULTIMO_MES_REALIZADO,''VERSAO_CONTROLE'',t.VERSAO_CONTROLE,''VERSAO_ORIGEM_ID'',t.VERSAO_ORIGEM_ID,''CRIADO_POR'',t.CRIADO_POR)) FROM CICLO t WHERE t.STATUS != ''FECHADO''),JSON_ARRAY()) AS CICLOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''TIPO'',t.TIPO,''VALOR'',t.VALOR,''PERCENTUAL'',t.PERCENTUAL,''APLICA_PJ'',t.APLICA_PJ,''APLICA_CLT'',t.APLICA_CLT,''CICLO_ID'',t.CICLO_ID)) FROM BENEFICIO t WHERE 1=1),JSON_ARRAY()) AS BENEFICIOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''PERCENTUAL'',t.PERCENTUAL,''APLICA_PJ'',t.APLICA_PJ,''APLICA_CLT'',t.APLICA_CLT,''CICLO_ID'',t.CICLO_ID)) FROM ENCARGO t WHERE 1=1),JSON_ARRAY()) AS ENCARGOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''SALARIO_MEDIO'',t.SALARIO_MEDIO,''ATIVO'',t.ATIVO)) FROM CARGO t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS CARGOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',d.ID,''NOME'',d.NOME,''DESCRICAO'',d.DESCRICAO,''COR'',d.COR,''ATIVO'',d.ATIVO,''CRIADO_EM'',d.CRIADO_EM,''TIPO_DRIVER'',d.TIPO_DRIVER,''ORIGEM'',d.ORIGEM,''GESTOR_ID'',gp.GESTOR_ID)) FROM DRIVERS d LEFT JOIN GESTOR_PACOTE gp ON gp.DRIVER_ID = d.ID WHERE d.TIPO_DRIVER = ''PACOTE'' AND d.ATIVO = ''true''),JSON_ARRAY()) AS PACOTE_DRIVERS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''DESCRICAO'',t.DESCRICAO,''COR'',t.COR,''ATIVO'',t.ATIVO,''CRIADO_EM'',t.CRIADO_EM,''TIPO_DRIVER'',t.TIPO_DRIVER,''ORIGEM'',t.ORIGEM)) FROM DRIVERS t WHERE t.TIPO_DRIVER = ''NORMAL'' AND t.ATIVO = ''true''),JSON_ARRAY()) AS NORMAL_DRIVERS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',df.ID,''DRIVER_ID'',df.DRIVER_ID,''CONTA_ID'',df.CONTA_ID,''FORMULA'',df.FORMULA,''DESCRICAO'',df.DESCRICAO,''TIPO'',df.TIPO,''ORDEM'',df.ORDEM,''NOME_CUSTOM'',df.NOME_CUSTOM,''LABEL'',df.LABEL,''ESCONDER'',df.ESCONDER,''NEGRITO'',df.NEGRITO,''FORMATO'',df.FORMATO,''CONTA_CODIGO'',cc.CODIGO,''CONTA_NOME'',cc.NOME)) FROM DRIVER_FORMULA df LEFT JOIN CONTA_CONTABIL cc ON cc.ID = df.CONTA_ID),JSON_ARRAY()) AS FORMULAS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''ORDEM'',t.ORDEM,''NOME_LINHA'',t.NOME_LINHA,''TIPO'',t.TIPO,''PREFIXO_CONTA'',t.PREFIXO_CONTA,''SINAL'',t.SINAL,''LINHA_PAI_ID'',t.LINHA_PAI_ID,''IS_SUBTOTAL'',t.IS_SUBTOTAL)) FROM DRE_CONFIG t WHERE 1=1),JSON_ARRAY()) AS DRE_CONFIG,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',c.ID,''CODIGO'',c.CODIGO,''NOME'',c.NOME,''TIPO'',c.TIPO)) FROM CONTA_CONTABIL c),JSON_ARRAY()) AS CONTAS', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
